// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());
        vm.assume(caller != newOwner);

        address initialOwner = c.owner();
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}

        address finalOwner = c.owner();
        assertTrue(finalOwner == initialOwner);
    }
}
